#!/bin/sh
# plow-calendar shim. GENERATED by scripts/build-plugins.mjs - do not edit by hand.
# Latch runs `exec.argv` as a child; a GUI app's PATH is often just /usr/bin:/bin, so
# look for Node where it is usually installed. If it is missing, answer with the same
# JSON error envelope the CLI uses (exit 9), never with prose.
# Only shell builtins here (no dirname/basename): the PATH a GUI app hands us may be empty.
case "$0" in */*) dir=${0%/*} ;; *) dir=. ;; esac
dir=$(cd "$dir" && pwd)
NODE=""
for c in "$(command -v node 2>/dev/null)" /opt/homebrew/bin/node /usr/local/bin/node "$HOME/.volta/bin/node" "$HOME/.local/bin/node"; do
  if [ -n "$c" ] && [ -x "$c" ] && "$c" -e 'process.exit(Number(process.versions.node.split(".")[0]) >= 20 ? 0 : 1)' 2>/dev/null; then
    NODE="$c"
    break
  fi
done
if [ -z "$NODE" ]; then
  printf '%s\n' '{"schema_version":1,"ok":false,"source":"calendar","error":{"code":"RUNTIME_MISSING","detail":"Node.js 20 or newer was not found (looked on PATH, /opt/homebrew/bin, /usr/local/bin, ~/.volta, ~/.local). Install it from nodejs.org or Homebrew."},"items":null,"warnings":[],"coverage":null}'
  echo "plow-calendar: RUNTIME_MISSING" >&2
  exit 9
fi
exec "$NODE" "$dir/plow-calendar.js" "$@"
